const LEGACY_COPY={"Robotika i automatizacija": "Robotics and automation", "E-commerce i dropshipping": "E-commerce and dropshipping", "Industrijska proizvodnja": "Industrial manufacturing", "Logistika i skladi\u0161tenje": "Logistics and warehousing", "Zdravstvena tehnologija": "Healthcare technology", "Druga industrija": "Other industry", "Srbija i DACH": "Serbia and DACH", "Novi biznis u pripremi.": "New business in preparation.", "Unesite parametre i pokrenite evaluaciju.": "Enter your parameters and start the evaluation.", "Sa\u010duvan projekat iz prethodne verzije.": "Saved project from the previous version.", "Biznis u pripremi.": "Business in preparation.", "Pratite prodaju, tro\u0161kove i prve kupce.": "Track sales, costs and your first customers.", "Demo poslovanje pokrenuto": "Demo business launched", "Validacija je zavr\u0161ena. Operativna zarada po\u010dinje od 0 \u20ac.": "Validation is complete. Operating revenue starts at \u20ac0.", "Validacija zavr\u0161ena. Spremno za demo poslovanje.": "Validation complete. Ready to launch the demo business.", "EU i Srbija": "EU and Serbia", "Maj": "May", "Avg": "Aug", "Okt": "Oct"};
const STORAGE='forge-businesses-v2';
const LEGACY_STORAGE='forge-business-engine-v1';
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Belgrade',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function freshMeta(){return {kind:'custom',status:'planning',startedOn:null,preparedOn:today(),earned:0,profit:0,orders:0,customers:0,monthlyRevenue:[],description:'New business in preparation.',nextAction:'Enter your parameters and start the evaluation.',activity:[],assets:[]};}
function freshState(){return {version:1,id:'business-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),params:{...DEFAULT_PARAMS,name:'',advantages:'',linkedin:'',website:'',notes:''},created:false,activeStep:0,phases:PHASES.map(()=>({status:'idle',started:0,elapsed:0})),savedAt:0,meta:freshMeta()};}
function validRecord(d){return d&&typeof d.id==='string'&&d.params&&typeof d.params.name==='string'&&Array.isArray(d.phases)&&d.phases.length===4&&d.phases.every(p=>['idle','running','paused','complete'].includes(p.status));}
function translateSavedRecord(record){
 const translate=value=>typeof value==='string'&&Object.hasOwn(LEGACY_COPY,value)?LEGACY_COPY[value]:value;
 const old=LEGACY_DEMO_BUSINESSES.find(b=>b.id===record.id);
 const current=(window.DEMO_BUSINESSES||[]).find(b=>b.id===record.id);
 if(old&&current){
   for(const key of Object.keys(record.params))if(typeof old.params[key]==='string'&&record.params[key]===old.params[key])record.params[key]=current.params[key];
   for(const key of ['description','nextAction'])if(record.meta[key]===old.meta[key])record.meta[key]=current.meta[key];
   for(const [key,identity] of [['activity','label'],['assets','title']])record.meta[key]=(record.meta[key]||[]).map(item=>{
     const index=(old.meta[key]||[]).findIndex(x=>x[identity]===item[identity]);
     if(index<0||!current.meta[key]?.[index])return {...item};
     const localized={...item};
     for(const field of Object.keys(item))if(typeof old.meta[key][index][field]==='string'&&item[field]===old.meta[key][index][field])localized[field]=current.meta[key][index][field];
     return localized;
   });
 }
 for(const key of Object.keys(record.params)){
   if(typeof LEGACY_DEFAULT_PARAMS[key]==='string'&&record.params[key]===LEGACY_DEFAULT_PARAMS[key])record.params[key]=DEFAULT_PARAMS[key];
   if(['industry','region'].includes(key))record.params[key]=translate(record.params[key]);
 }
 for(const key of ['description','nextAction'])record.meta[key]=translate(record.meta[key]);
 record.meta.activity=(record.meta.activity||[]).map(item=>({...item,label:translate(item.label),description:translate(item.description)}));
 record.meta.monthlyRevenue=(record.meta.monthlyRevenue||[]).map(item=>({...item,month:translate(item.month)}));
 return record;
}
function normalizeRecord(d){return translateSavedRecord({...d,params:{...DEFAULT_PARAMS,...d.params},meta:{...freshMeta(),...d.meta},activeStep:Math.max(0,Math.min(4,Number(d.activeStep)||0))});}
let portfolio={version:2,businesses:JSON.parse(JSON.stringify(window.DEMO_BUSINESSES||[])),activeId:null,draft:null},storageOK=true;
try {
  const saved=JSON.parse(localStorage.getItem(STORAGE));
  if(saved&&saved.version===2&&Array.isArray(saved.businesses)&&saved.businesses.every(validRecord)) portfolio={...portfolio,...saved,businesses:saved.businesses.map(normalizeRecord),draft:validRecord(saved.draft)?normalizeRecord(saved.draft):null};
  else {
    const legacy=JSON.parse(localStorage.getItem(LEGACY_STORAGE));
    if(legacy&&legacy.created&&legacy.params?.name&&legacy.params.name!=='Robotics Venture Lab'&&Array.isArray(legacy.phases)&&legacy.phases.length===4) {
      portfolio.businesses.push(normalizeRecord({...legacy,id:'previous-project',meta:{...freshMeta(),description:'Saved project from the previous version.',status:legacy.phases.every(p=>p.status==='complete')?'validation':'planning'}}));
    }
  }
} catch(e){storageOK=false;}
let state=portfolio.businesses.find(b=>b.id===portfolio.activeId)||portfolio.draft||freshState();
let evaluationSelection={stage:1,id:null,origin:'project'},resultStagePreference=0;
let route='',agentCategory='All agents',agentSearch='',showAll=false,showEliminated=false,toastTimer;
function persist(){state.savedAt=Date.now();if(!portfolio.businesses.some(b=>b.id===state.id))portfolio.draft=state;try{localStorage.setItem(STORAGE,JSON.stringify(portfolio));storageOK=true;}catch(e){storageOK=false;}}
function businessKind(industry){return industry.includes('dropshipping')?'dropshipping':industry.includes('Affiliate')?'affiliate':industry.includes('Robotics')?'robot':'custom';}
function registerBusiness(){if(!portfolio.businesses.some(b=>b.id===state.id))portfolio.businesses.push(state);portfolio.activeId=state.id;portfolio.draft=null;state.meta.kind=businessKind(state.params.industry);state.meta.description=state.params.notes||'Business in preparation.';}
function selectBusiness(id){const b=portfolio.businesses.find(b=>b.id===id);if(!b)return false;state=b;portfolio.activeId=id;showAll=false;showEliminated=false;persist();return true;}
function openBusiness(id){if(selectBusiness(id))routeTo('business/'+encodeURIComponent(id));}
function newBusiness(){state=freshState();portfolio.activeId=null;portfolio.draft=state;persist();if(route==='project'&&!location.hash.includes('/'))render();else routeTo('project');}
function launchBusiness(){if(!state.phases.every(p=>p.status==='complete')){toast('Complete all four validation stages first.');return;}if(state.meta.startedOn)return;state.meta.startedOn=today();state.meta.status='active';state.meta.nextAction='Track sales, costs and your first customers.';state.meta.activity.unshift({date:today(),label:'Demo business launched',description:'Validation is complete. Operating revenue starts at €0.'});persist();render();toast('Demo business launched.');}
function businessHandlers(){return {openBusiness,newBusiness,openStep,results:()=>routeTo('results'),back:()=>routeTo('businesses'),launch:launchBusiness};}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function elapsed(p){return p.elapsed+(p.status==='running'?Math.max(0,Date.now()-p.started):0);}
function progress(i){return state.phases[i].status==='complete'?100:Math.min(100,Math.floor(elapsed(state.phases[i])/PHASES[i].demo*100));}
function available(step){return step===0||state.created&&(step===1||state.phases[step-2].status==='complete');}
function completedCount(){return state.phases.filter(p=>p.status==='complete').length;}
function completedIds(){return state.phases.flatMap((p,i)=>p.status==='complete'?[i+1]:[]);}
function routeTo(name){location.hash=['project','results'].includes(name)&&portfolio.activeId?name+'/'+encodeURIComponent(state.id):name;}
function openStep(step){if(!available(step)){toast(state.created?'Complete the previous stage to continue.':'Save your parameters and create a project first.');return;}state.activeStep=step;showAll=false;showEliminated=false;persist();if(route==='project')render();else routeTo('project');}
function sidebar(){
 const hasBusiness=portfolio.businesses.some(b=>b.id===state.id);
 const running=state.phases.findIndex(p=>p.status==='running');
 $('#stage-nav').innerHTML=hasBusiness?PHASES.map((p,i)=>`<button data-step="${i+1}" class="${state.phases[i].status==='complete'?'completed':''} ${running===i?'running':''} ${route==='project'&&state.activeStep===i+1?'selected':''}" ${available(i+1)?'':'aria-disabled="true"'}><span class="stage-dot"></span>${p.short}${available(i+1)?'':ico('lock').replace('<svg ','<svg class="lock-icon" ')}</button>`).join(''):'';
 $('.stages-caption').style.display=hasBusiness?'':'none';
 const selection=$('#selected-business');
 if(selection){selection.innerHTML=hasBusiness?`<span>SELECTED BUSINESS</span><button id="selected-business-link">${esc(state.params.name)}${ico('arrow')}</button>`:'';selection.style.display=hasBusiness?'':'none';if($('#selected-business-link'))$('#selected-business-link').onclick=()=>openBusiness(state.id);}
 const navRoute=route==='business'?'businesses':route==='evaluations'?evaluationSelection.origin:route;
 $$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===navRoute);if(a.dataset.nav===navRoute)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $$('[data-step]',$('#stage-nav')).forEach(b=>b.onclick=()=>openStep(Number(b.dataset.step)));
}
function stepper(){return `<div class="stepper" aria-label="Project progress">${['Parameters',...PHASES.map(p=>p.short)].map((title,i)=>{const done=i===0?state.created:state.phases[i-1].status==='complete';return `<div class="step ${state.activeStep===i?'active':''} ${done?'complete':''}"><button class="step-button" data-step="${i}" ${state.activeStep===i?'aria-current="step"':''} ${available(i)?'':'aria-disabled="true"'}><span class="step-circle">${done?ico('check'):String(i+1).padStart(2,'0')}</span><span><span class="step-title">${title}</span><small class="step-sub">${i===0?'Project foundation':i===4?'15 → preorders':`${PHASES[i-1].input} → ${PHASES[i-1].output} ideas`}</small></span></button></div>`;}).join('')}</div>`;}
function heading(eyebrow,title,description,pill){return `<div class="page-heading"><div><div class="eyebrow">${ico('spark')}${eyebrow}</div><h1>${title}</h1><p class="heading-description">${description}</p></div>${pill||''}</div>`;}
function statusPill(text,kind=''){return `<span class="status-pill ${kind}"><i></i>${text}</span>`;}
function avatars(){return `<div class="avatar-stack"><span>TE</span><span>VC</span><span>MK</span><span>+21</span></div>`;}
function robotArt(){return `<svg class="robot-art" viewBox="0 0 360 250" fill="none" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Illustration of an industrial robot arm on a work platform"><defs><linearGradient id="floor" x1="70" y1="170" x2="290" y2="240" gradientUnits="userSpaceOnUse"><stop stop-color="#DED9ED"/><stop offset="1" stop-color="#E9E5F3"/></linearGradient><linearGradient id="arm" x1="112" y1="77" x2="181" y2="144" gradientUnits="userSpaceOnUse"><stop stop-color="#A095CA"/><stop offset="1" stop-color="#7764AC"/></linearGradient><linearGradient id="front" x1="128" y1="121" x2="179" y2="194" gradientUnits="userSpaceOnUse"><stop stop-color="#B2A5D8"/><stop offset="1" stop-color="#9481C0"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="6"/></filter></defs><g opacity=".45" stroke="#D5CCE8" stroke-width=".7"><path d="m30 194 175-89 145 74M39 208l175-89m-149 101 175-89m-144 101 175-89m-140 101 175-89M56 180l146 75M82 167l146 75M108 154l146 75M134 141l146 75M160 128l146 75M186 115l146 75"/></g><ellipse cx="182" cy="201" rx="84" ry="17" fill="#B8ACD1" opacity=".25" filter="url(#shadow)"/><path d="m76 178 105-53 109 55-105 54-109-56Z" fill="url(#floor)" stroke="#D0C6E5"/><path d="m76 178 109 56v10L76 188v-10Z" fill="#CFC5E2"/><path d="m185 234 105-54v10l-105 54v-10Z" fill="#DDD5EB"/><path d="m118 186 43-22 46 23-43 22-46-23Z" fill="#716092"/><path d="m118 186 46 23v10l-46-23v-10Z" fill="#675584"/><path d="m164 209 43-22v10l-43 22v-10Z" fill="#8672A5"/><path d="m132 155 29-15 31 16v37l-29 15-31-16v-37Z" fill="url(#front)"/><path d="m163 171 29-15v37l-29 15v-37Z" fill="#8672B2"/><path d="m132 155 29-15 31 16-29 15-31-16Z" fill="#C7BDE1"/><path d="m140 169 13 7v15l-13-7v-15Z" fill="#7A659E"/><path d="m144 174 6 3" stroke="#D9CFEE" stroke-width="2"/><path d="m148 150-19-59 16-11 23 63-20 7Z" fill="url(#arm)"/><path d="m168 143-23-63 11 6 23 63-11-6Z" fill="#675491"/><ellipse cx="151" cy="146" rx="18" ry="21" transform="rotate(-28 151 146)" fill="#7F6CAA"/><ellipse cx="148" cy="144" rx="11" ry="14" transform="rotate(-28 148 144)" fill="#D1C6E6"/><ellipse cx="148" cy="144" rx="5" ry="7" transform="rotate(-28 148 144)" fill="#AA99CC"/><path d="m141 82 62-31 10 16-63 33-9-18Z" fill="#B2A4D2"/><path d="m150 100 63-33 8 6-63 33-8-6Z" fill="#7964A8"/><ellipse cx="145" cy="90" rx="18" ry="19" transform="rotate(-30 145 90)" fill="#8773B0"/><ellipse cx="141" cy="87" rx="12" ry="13" transform="rotate(-30 141 87)" fill="#D4CAE8"/><ellipse cx="141" cy="87" rx="5" ry="6" transform="rotate(-30 141 87)" fill="#A395C7"/><path d="m204 51 14 7 18 43-14 6-18-56Z" fill="#8E7AB7"/><path d="m218 58 8-3 18 43-8 3-18-43Z" fill="#6E5998"/><ellipse cx="211" cy="59" rx="13" ry="15" transform="rotate(-25 211 59)" fill="#8B77AF"/><ellipse cx="207" cy="57" rx="8" ry="10" transform="rotate(-25 207 57)" fill="#C5B8DF"/><path d="m222 103 14-7 9 9-14 7-9-9Z" fill="#D0C4E2"/><path d="m222 103 9 9v13l-9-5v-17Z" fill="#8C79A6"/><path d="m231 112 14-7v14l-14 6v-13Z" fill="#725D93"/><path d="m226 121-6 6 5 12 5-3-4-9 5-3m8-4 7 8-4 13-6-3 3-9-6-5" stroke="#625174" stroke-width="4" stroke-linejoin="round"/><path d="m231 146 23-12 26 13-24 12-25-13Z" fill="#C6BBDB"/><path d="m231 146 25 13v21l-25-13v-21Z" fill="#B4A7CC"/><path d="m256 159 24-12v21l-24 12v-21Z" fill="#9B8AB9"/><path d="m242 141 25 13M244 159l7 3" stroke="#E5DEF0" stroke-width="2"/><g stroke="#B0A2C9" stroke-dasharray="3 4" stroke-width="1"><path d="M251 50h48v77M108 128H70v27"/></g><circle cx="251" cy="50" r="2.5" fill="#A799C2"/><circle cx="108" cy="128" r="2.5" fill="#A799C2"/><text x="271" y="42" font-family="monospace" font-size="7" fill="#A89BBE">AXIS_06</text><text x="36" y="164" font-family="monospace" font-size="7" fill="#A89BBE">ROBOTICS</text><circle cx="299" cy="131" r="2" fill="#BCADD0"/></svg>`;}
function formField(label,name,type='text',required=false,suffix=''){const val=state.params[name];return `<label class="field"><span class="field-title">${label}${required?'<span class="required">*</span>':''}</span><div class="${suffix?'input-suffix':''}"><input name="${name}" type="${type}" value="${esc(val)}" ${required?'required':''} ${type==='number'?`min="${name==='capital'?100:1}" max="${name==='capital'?100000000:120}" step="${name==='capital'?100:1}"`:''} ${type==='url'?'placeholder="https://…"':''}>${suffix?`<span>${suffix}</span>`:''}</div></label>`;}
function setup(){return `<button class="button ghost wizard-back" id="wizard-back">← ${portfolio.activeId?'Business overview':'My business'}</button>${heading('YOUR NEXT BUSINESS STARTS HERE','From an idea to your first orders.','Set your parameters. Your agent team handles the next four stages.',statusPill(state.created?'Project created':'Project draft'))}${stepper()}<div class="setup-layout"><section class="panel"><div class="panel-head"><span class="panel-icon">${ico('edit')}</span><div><h2>Build your project foundation</h2><p>Better inputs lead to more relevant ideas.</p></div></div><form id="project-form"><div class="form-body"><div class="form-section">01 / CORE PARAMETERS</div>${formField('Project name','name','text',true)}<div class="form-row"><label class="field"><span class="field-title">Industry<span class="required">*</span></span><select name="industry">${[...new Set(['Robotics and automation','E-commerce and dropshipping','Affiliate marketing','Industrial manufacturing','Logistics and warehousing','Healthcare technology','Other industry',state.params.industry])].map(x=>`<option ${state.params.industry===x?'selected':''}>${x}</option>`).join('')}</select></label>${formField('Target market','region','text',true)}</div><div class="form-row">${formField('Initial capital','capital','number',true,'EUR')}${formField('Desired payback period','roi','number',true,'months')}</div><p class="hint" style="margin:-10px 0 24px">Agents use your capital and timeline as constraints when evaluating each idea.</p><div class="form-section section-gap">02 / FOUNDER STRENGTHS</div><label class="field"><span class="field-title">What do you bring to the project?<span class="required">*</span></span><textarea name="advantages" required maxlength="2000" placeholder="Experience, team, contacts, technology, equipment…">${esc(state.params.advantages)}</textarea><div class="advantage-chips"><span>${ico('check')}Experience and expertise</span><span>${ico('check')}Team and contacts</span><span>${ico('check')}Technology and equipment</span></div></label><div class="form-section section-gap">03 / YOUR CHANNELS AND CONTEXT</div><div class="form-row social-fields">${formField('LinkedIn or another social profile','linkedin','url')}${formField('Existing website','website','url')}</div><label class="field" style="margin:19px 0 0"><span class="field-title">Additional context<span class="optional">optional</span></span><input name="notes" value="${esc(state.params.notes)}" placeholder="Customers, goals or other constraints"></label></div><div class="form-actions"><button type="button" class="button ghost" id="save-draft">${ico('save')}Save draft</button><span class="save-state">${ico('lock')}Saved locally</span><button type="submit" class="button primary">${state.created?'Save and continue':'Create project'}${ico('arrow')}</button></div></form></section><aside class="setup-aside"><div class="project-preview"><div class="preview-eyebrow">INDUSTRY IN FOCUS</div><h2>Big ideas.<br>Real potential.</h2><p>${businessKind(state.params.industry)==='robot'?'From robotic automation to a new business model.':'From your audience and strengths to a sustainable business model.'} Find an idea the market wants.</p>${businessKind(state.params.industry)==='robot'?robotArt():`<div class="business-concept-art">${ico(businessKind(state.params.industry)==='affiliate'?'file':'grid')}<span>${esc(state.params.industry)}</span></div>`}<div class="art-caption"><span><i></i>${esc(state.params.industry.toUpperCase())}</span><span>SECTOR / 01</span></div></div><div class="panel funnel-panel"><h3>Fewer ideas. More evidence.${ico('funnel')}</h3><p class="funnel-caption">Every stage brings you closer to validation.</p>${[[100,'Initial ideas',100],[50,'Product Market Fit',80],[30,'Go-To-Market',64],[15,'Marketing → Sales',47]].map(([count,label,width])=>`<div class="funnel-row"><div class="funnel-bar" style="width:${width}%"><strong>${count}</strong><span>ideas</span></div><span class="funnel-label">${label}</span></div>`).join('')}</div><div class="agent-summary">${avatars()}<p>24 perspectives. Independent scores.<a href="#agents">Meet your agent team ↗</a></p></div></aside></div>`;}
function readForm(){const f=$('#project-form');if(!f.reportValidity())return null;const d=Object.fromEntries(new FormData(f));d.capital=Number(d.capital);d.roi=Number(d.roi);for(const key of ['name','region','advantages'])if(!d[key].trim()){toast('Complete all required fields.');return null;}return d;}
function sameParams(a,b){return Object.keys(DEFAULT_PARAMS).every(k=>String(a[k])===String(b[k]));}
function commitForm(start){const params=readForm();if(!params)return;if(!sameParams(params,state.params)&&state.phases.some(p=>p.status!=='idle')){showDialog(`<div class="dialog-kicker">PARAMETER CHANGES</div><h2>Restart the evaluation?</h2><p class="dialog-text">Changed inputs affect all ideas and results. Saving new parameters resets the four demo stages for this project.</p><div class="dialog-actions"><button class="button secondary" id="cancel-reset">Cancel</button><button class="button primary" id="confirm-reset">Save and reset</button></div>`);$('#cancel-reset').onclick=()=>$('#detail-dialog').close();$('#confirm-reset').onclick=()=>{$('#detail-dialog').close();applyParams(params,start,true);};return;}applyParams(params,start,false);}
function applyParams(params,start,reset){state.params=params;if(reset){state.phases=freshState().phases;if(!state.meta.startedOn)state.meta.status='planning';}registerBusiness();if(start){state.created=true;state.activeStep=1;}persist();if(start&&location.hash!=='#project/'+state.id)routeTo('project');else render();toast(start?'Your business is ready for Product Market Fit.':storageOK?'Your draft is saved in My business.':'Saving is unavailable. Export your project before closing.');}
const names=['Cobot palletizing','Vision QC platform','Robot-as-a-Service','AMR warehouse logistics','Robotic welding','Automated packaging','Robot cell servicing','Digital twin','Order picking robot','Cobot operator training','Modular grippers','Predictive maintenance','Robotic sorting','Laboratory automation','Mobile inspection'];
const segments=['for small businesses','for the food sector','for the automotive industry','for distribution centers','for the metal industry','for the electronics industry','for the pharmaceutical sector'];
function hash(s){let n=0;for(const c of s)n=(n*31+c.charCodeAt(0))>>>0;return n;}
function ideaContext(){
 const kind=businessKind(state.params.industry);
 if(kind==='dropshipping')return {kind,names:['Desk organizers','Home office accessories','Travel organizers','Smart kitchen equipment','Pet supplies','Fitness accessories','Home decor','Eco-friendly accessories','Personalized gifts','LED lighting','Phone accessories','Camping equipment','Practical household tools','Personal care accessories','Hobby equipment'],segments:['for home offices','for young families','for travel enthusiasts','for small apartments','for active shoppers','for gifts','for creative users'],prices:[39,59,29,69,45,55,49,35,65,79,25,89,49,35,59],icp:['Home office shopper','Online shopper','Home goods shopper','Gift shopper'],model:'Online sales',problem:'Online shoppers want practical products, clear information and reliable delivery. We test the problem through offer quality, pricing and the buying experience.',solution:'A test store, a curated product catalog, partner suppliers, an ordering flow and customer support.',channels:'Instagram, search, content and email. Catalog: a core product, bundles and accessories.',plan:'The founder manages the assortment and decisions, marketing manages ads, the partner ships products and support tracks orders. Demo timeline: supplier checks in 2 weeks, store in 3 weeks, campaign testing in 4 weeks.'};
 if(kind==='affiliate')return {kind,names:['Home office guide','Ergonomic chair comparisons','Headphone reviews','Smart home guide','Laptop accessory recommendations','Monitor comparisons','Travel accessory guide','Photography equipment reviews','Kitchen equipment recommendations','Fitness device guide','E-reader comparisons','Gaming equipment recommendations','Office lighting reviews','Hobby equipment guide','Household tool comparisons'],segments:['for beginners','for small budgets','for advanced users','for remote work','for freelancers','for small teams','for shoppers in DACH'],prices:[12,18,8,15,6,20,5,24,7,10,6,16,5,9,8],icp:['Buying guide reader','Comparison shopper','Newsletter subscriber','Search visitor'],model:'Affiliate commission',problem:'Shoppers struggle to choose between competing products. The idea adds value through clear content and help with buying decisions.',solution:'A content website with comparisons, reviews and demo affiliate recommendations. There is no active affiliate account or confirmed commission revenue.',channels:'Organic search, a newsletter and social media. Catalog: guides, comparisons and reviews.',plan:'The founder selects a niche, the editor prepares content, marketing tracks traffic and the analyst checks demo conversions. Demo timeline: research in 2 weeks, initial content in 4 weeks, audience testing in 4 weeks.'};
 return {kind,names,segments,prices:[18500,4200,12500,28000,35000,16000,2900,6400,22000,1200,3400,4800,19000,25000,7800],icp:['Operations director','Quality manager','Production director','Logistics manager'],model:'B2B sales + service',problem:'Manufacturers struggle with repetitive tasks, workforce availability and consistent quality.',solution:'A modular robotic solution with sensors, integration and training. A pilot cell with performance monitoring and a service package.',channels:'Direct B2B sales, LinkedIn and email. Catalog: a core package, integration and annual servicing.',plan:'The founder owns the decisions. The technical team runs the pilot, sales manages customers, and finance and legal agents provide assessments. Demo timeline: research in 2 weeks, pilot in 6 weeks, sales testing in 4 weeks.'};
}
function allIdeas(){const seed=hash(JSON.stringify(state.params)),ctx=ideaContext();return Array.from({length:100},(_,i)=>{
 const niche=ctx.segments[Math.floor(i/15)%ctx.segments.length];const name=ctx.names[i%15]+' '+niche;
 const rating=phase=>window.AgentEvaluations.average(window.AgentEvaluations.scores(state.params,i+1,phase));
 const price=ctx.prices[i%15],units=ctx.kind==='dropshipping'?100:ctx.kind==='affiliate'?120:1;
 return {id:i+1,name,score:rating(1),gtmScore:rating(2),marketingAgentScore:rating(3),salesScore:rating(4),metricScore:65+(hash('m'+seed+i)%300)/10,marketingScore:Math.round((rating(3)*.4+(65+(hash('m'+seed+i)%300)/10)*.6)*10)/10,price,investment:Math.round(state.params.capital*(.5+((i+1)%6)*.06)),monthlyCash:Math.round(price*units*(ctx.kind==='dropshipping'?.25:.6+((i+1)%5)*.1)),icp:ctx.icp[i%4],visits:1800+hash('v'+seed+i)%6500,replies:20+hash('e'+seed+i)%160,subscribers:80+hash('s'+seed+i)%600};
});}
function rankedIdeas(stage,all=false){let ideas=allIdeas().sort((a,b)=>b.score-a.score||a.id-b.id);if(stage===1)return all?ideas:ideas.slice(0,50);ideas=ideas.slice(0,50).sort((a,b)=>b.gtmScore-a.gtmScore||a.id-b.id);if(stage===2)return all?ideas:ideas.slice(0,30);ideas=ideas.slice(0,30).sort((a,b)=>b.marketingScore-a.marketingScore||a.id-b.id);if(stage===3)return all?ideas:ideas.slice(0,15);return ideas.slice(0,15).map((x,i)=>({...x,preorders:Math.max(3,25-i+hash('o'+x.id)%10)}));}
function financial(x){return {revenue:x.price*(x.preorders||0),roi:Math.round((x.monthlyCash*state.params.roi/x.investment-1)*100),payback:Math.round(x.investment/x.monthlyCash*10)/10};}
function phaseView(){const i=state.activeStep-1,p=PHASES[i],job=state.phases[i];const statuses={idle:'Ready to start',running:'Processing',paused:'Paused',complete:'Stage complete'};return `${heading(`STAGE ${String(i+1).padStart(2,'0')} / ${esc(state.params.name)}`,p.name,p.desc,statusPill(statuses[job.status],job.status==='complete'?'complete':job.status==='running'?'running':''))}${stepper()}<div class="phase-banner">${ico('clock')}<span><strong>The process can take ${p.duration.toLowerCase()}.</strong> This demo completes the stage in ${p.demo/1000} s.</span><a href="#agents">24 agents ↗</a></div><div class="phase-layout"><section class="panel phase-card"><div class="phase-card-header"><div><div class="phase-number">${i===3?'SALES VALIDATION':'EVALUATION & SELECTION'}</div><h2>${i===3?'From interest to preorders':`Next selection: ${p.output} top ideas`}</h2></div><span class="panel-icon">${ico(i===3?'chart':'funnel')}</span></div><div class="phase-visual"><div class="phase-metric"><strong>${p.input}</strong><small>${i===0?'generated ideas':'input ideas'}</small></div>${ico('arrow')}<div class="phase-metric output"><strong>${p.output}</strong><small>${i===3?'count and revenue per idea':'ideas for the next stage'}</small></div><div class="phase-duration"><strong>${ico('clock').replace('<svg ','<svg style="display:inline;width:13px;height:13px;vertical-align:middle;margin-right:4px" ')}${p.duration}</strong><small>Estimated real process duration</small></div></div><ul class="task-list" id="phase-tasks">${taskMarkup(i)}</ul><div id="progress-section">${progressMarkup(i)}</div><div class="phase-actions" id="phase-actions">${phaseActions(i)}</div><div class="live-log" id="live-log">${liveLog(i)}</div></section><aside><div class="panel phase-aside"><h3>Your project brief</h3><p>${esc(state.params.name)}</p><div class="agent-summary">${avatars()}<p><strong>24 expert agents</strong><a href="#agents">View responsibilities ↗</a></p></div><div class="kv"><span>Industry</span><strong>${esc(state.params.industry)}</strong></div><div class="kv"><span>Market</span><strong>${esc(state.params.region)}</strong></div><div class="kv"><span>Capital</span><strong>${money(state.params.capital)}</strong></div><div class="kv"><span>Target payback</span><strong>${state.params.roi} months</strong></div>${i>=2?`<div class="kv"><span>Budget per idea</span><strong>${money(state.params.capital*(i===2?.1/30:.2/15))}</strong></div>`:''}<p class="small-note">${i===2?'Equal budgets for all 30 ideas.':i===3?'20% of initial capital for marketing: four times the budget per idea compared with the previous stage.':'Every agent evaluates each idea within their area of expertise.'}</p></div><div class="insight-card">${ico('spark')}<h3>${p.hint}</h3><p>${p.hintText}</p></div></aside></div>${job.status==='complete'?resultsTable(i+1):''}<p class="small-note">Demo simulation • No real AI execution, emails, campaigns or payments. Progress and data are saved in this browser.</p>`;}
function taskMarkup(i){const pct=progress(i),job=state.phases[i];return PHASES[i].tasks.map((t,k)=>{const done=pct>=(k+1)*25;const current=!done&&pct>=k*25&&(job.status==='running'||job.status==='paused');return `<li class="${done?'done':current?'current':''}">${ico(done?'check':current&&job.status==='running'?'loading':'circle')}<span>${t}</span><span class="task-state">${done?'Complete':current?(job.status==='paused'?'Paused':'In progress'):'Pending'}</span></li>`;}).join('');}
function progressMarkup(i){const pct=progress(i),job=state.phases[i];return `<div class="progress-meta"><span>${job.status==='complete'?'Evaluation complete':job.status==='idle'?'Demo not started':job.status==='paused'?'Progress saved · paused':'Demo evaluation in progress'}</span><strong>${pct}%</strong></div><div class="progress-track" role="progressbar" aria-label="Stage progress" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${pct}%"></div></div><div class="progress-info">${job.status==='complete'?'Results are ready. Review them and move on to the next stage.':job.status==='idle'?'Start the stage when you are ready. The simulation takes less than a minute.':'You can visit the agents page or close the site and return later. Demo time is measured from the moment you start.'}</div>`;}
function phaseActions(i){const job=state.phases[i];let main=job.status==='idle'?`<button class="button primary" id="run-phase">${ico('play')}Start demo stage</button>`:job.status==='running'?`<button class="button secondary" id="pause-phase">${ico('pause')}Pause process</button>`:job.status==='paused'?`<button class="button primary" id="resume-phase">${ico('play')}Resume process</button>`:i<3?`<button class="button primary" data-next="${i+2}">Continue to ${PHASES[i+1].short}${ico('arrow')}</button>`:`<button class="button primary" id="go-results">View all results${ico('arrow')}</button>`;return `<button class="button ghost" id="back-phase">← ${i===0?'Project parameters':'Previous stage'}</button>${main}`;}
function liveLog(i){const p=progress(i),job=state.phases[i];if(job.status==='idle')return '<strong>Ready.</strong> Input parameters are saved. All agents receive the same brief.';if(job.status==='complete')return `<strong>24 / 24 evaluations complete.</strong> ${i===3?'Simulated preorders and the financial model are ready.':`${PHASES[i].output} ideas move on to the next stage.`}`;return `<strong>${Math.floor(p*24/100)} / 24 evaluations.</strong> ${job.status==='paused'?'The process is waiting to resume.':PHASES[i].tasks[Math.min(3,Math.floor(p/25))]+'.'}`;}
function runPhase(i){const job=state.phases[i];if(!available(i+1))return;if(!['idle','paused'].includes(job.status))return;job.status='running';job.started=Date.now();persist();render();toast('Demo stage started.');}
function pausePhase(i){const job=state.phases[i];if(job.status!=='running')return;job.elapsed=elapsed(job);job.started=0;job.status='paused';persist();render();toast('The process is paused. Your progress is saved.');}
function tick(){let changed=false;
 const records=[...portfolio.businesses];if(!records.some(b=>b.id===state.id))records.push(state);
 records.forEach(b=>b.phases.forEach((job,i)=>{if(job.status==='running'&&elapsed(job)>=PHASES[i].demo){job.status='complete';job.elapsed=PHASES[i].demo;job.started=0;changed=true;if(b.id===state.id)toast(`${PHASES[i].name}: demo results are ready.`);if(b.phases.every(p=>p.status==='complete')&&!b.meta.startedOn){b.meta.status='validation';b.meta.nextAction='Validation complete. Ready to launch the demo business.';}}}));
 if(changed){persist();render();}else if(route==='project'&&state.activeStep>0&&state.phases[state.activeStep-1].status==='running'){const i=state.activeStep-1;if($('#phase-tasks')){$('#phase-tasks').innerHTML=taskMarkup(i);$('#progress-section').innerHTML=progressMarkup(i);$('#live-log').innerHTML=liveLog(i);}}
}
function evaluationRouteValid(stage,id){
 if(!Number.isInteger(stage)||stage<1||stage>4||!Number.isInteger(id)||id<1||id>100||state.phases[stage-1].status!=='complete')return false;
 return (stage===1?allIdeas():rankedIdeas(stage-1)).some(x=>x.id===id);
}
function scoreHref(id,stage,origin=route){return '#evaluations/'+encodeURIComponent(state.id)+'/'+stage+'/'+id+'/'+(origin==='results'?'results':'project');}
function scoreLink(x,stage,value,label='Average agent score'){
 return '<a class="score score-link" data-score-link href="'+esc(scoreHref(x.id,stage))+'" aria-label="'+esc(label+' for '+x.name+' in '+PHASES[stage-1].short+': '+number(value)+' out of 100')+'">'+number(value)+'</a>';
}
function bindScoreLinks(){ $$('[data-score-link]').forEach(a=>a.onclick=()=>{if($('#detail-dialog').open)$('#detail-dialog').close();}); }
function evaluationPayload(stage,id,origin='project'){
 if(!evaluationRouteValid(stage,id))return null;
 const x=(stage===4?rankedIdeas(4):allIdeas()).find(x=>x.id===id);
 const ratings=window.AgentEvaluations.scores(state.params,id,stage);
 return {business:state,idea:x,stage,ratings,average:window.AgentEvaluations.average(ratings),metricScore:stage===3?x.metricScore:null,combinedScore:stage===3?x.marketingScore:null,context:ideaContext(),returnUrl:'#'+(origin==='results'?'results/':'project/')+encodeURIComponent(state.id)+(origin==='results'?'/'+stage:''),stageLinks:PHASES.flatMap((p,i)=>evaluationRouteValid(i+1,id)?[{stage:i+1,label:p.short,url:scoreHref(id,i+1,origin),active:stage===i+1}]:[])};
}
function ideaScoreSummary(x,stage){
 const links=PHASES.flatMap((p,i)=>i+1<=stage&&evaluationRouteValid(i+1,x.id)?['<a class="dialog-score-link" data-score-link href="'+esc(scoreHref(x.id,i+1))+'">'+p.short+' agent average '+number(i===0?x.score:i===1?x.gtmScore:i===2?x.marketingAgentScore:x.salesScore)+'/100</a>']:[]);
 return '<section><h3>Agent scores</h3><p>'+links.join(' · ')+'</p>'+(stage>=3&&state.phases[2].status==='complete'?'<p>Marketing combined score: <a class="dialog-score-link" data-score-link href="'+esc(scoreHref(x.id,3))+'">'+number(x.marketingScore)+'/100</a> (40% agent average + 60% market metrics).</p>':'')+'<p>Select a score to see all 24 agent evaluations. Scores and explanations are simulated.</p></section>';
}
function resultsTable(stage){const rows=rankedIdeas(stage,showEliminated),p=PHASES[stage-1];const list=showAll?rows:rows.slice(0,5);return `<section class="panel results-panel"><div class="panel-title-row"><div><h2>${stage===4?'Preorders by idea':`Top ideas · ${rows.length}`}</h2><p>${stage===4?'Simulated customer confirmations, revenue and expected returns.':stage===3?'40% average agent score + 60% market metrics. Select either score to see the breakdown.':'Average of 24 independent agent scores. Select a score to see each evaluation.'}</p></div><button class="button secondary" id="export-csv">${ico('download')}Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>BUSINESS IDEA</th>${stage===1?'<th>AGENT AVERAGE / 100</th><th>MODEL</th>':stage===2?'<th>ICP</th><th>PRICE</th><th>AGENT AVERAGE</th>':stage===3?'<th>VISITS</th><th>EMAIL REPLIES</th><th>SUBSCRIPTIONS</th><th>AGENT AVERAGE</th><th>COMBINED SCORE</th>':'<th>AGENT AVERAGE</th><th>PREORDER</th><th>REVENUE</th><th>ROI</th><th>PAYBACK</th>'}<th></th></tr></thead><tbody>${list.map((x,k)=>`<tr><td><span class="rank">${String(k+1).padStart(2,'0')}</span>${esc(x.name)}</td>${stage===1?`<td>${scoreLink(x,1,x.score)}</td><td>${esc(ideaContext().model)}</td>`:stage===2?`<td>${x.icp}</td><td>${money(x.price)}</td><td>${scoreLink(x,2,x.gtmScore)}</td>`:stage===3?`<td>${number(x.visits)}</td><td>${x.replies}</td><td>${x.subscribers}</td><td>${scoreLink(x,3,x.marketingAgentScore)}</td><td>${scoreLink(x,3,x.marketingScore,'Combined marketing score')}</td>`:`<td>${scoreLink(x,4,x.salesScore)}</td><td>${x.preorders}</td><td>${money(financial(x).revenue)}</td><td><span class="score">${financial(x).roi}%</span></td><td>${number(financial(x).payback)} mo.</td>`}<td><button class="table-action" data-idea="${x.id}" aria-label="Open plan: ${esc(x.name)}">${ico('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="phase-actions" style="margin-top:17px"><button class="button ghost" id="toggle-all">${showAll?'Show first 5':`Show all ${rows.length} ideas`} ${ico(showAll?'close':'arrow')}</button>${stage<4?`<button class="button ghost" id="toggle-eliminated">${showEliminated?`Selected only: ${p.output}`:`All input ideas (${p.input})`}</button>`:'<span class="small-note" style="margin:0">All orders are demo data.</span>'}</div></section>`;}
function showIdea(id,stage=visibleResultStage){const x=rankedIdeas(4).find(x=>x.id===id)||allIdeas().find(x=>x.id===id);if(!x)return;const final=stage===4&&state.phases[3].status==='complete'&&x.preorders;const model=financial(x);const finance=final?model:null;const ctx=ideaContext();showDialog(`<div class="dialog-kicker">DEMO BUSINESS PLAN · IDEA ${String(id).padStart(3,'0')}</div><h2>${esc(x.name)}</h2><p class="dialog-text">Industry: ${esc(state.params.industry)} · Market: ${esc(state.params.region)}. The proposal draws on founder strengths and initial capital of ${money(state.params.capital)}.</p><div class="dialog-grid"><section><h3>Problem and market</h3><p>${esc(ctx.problem)} Demo ICP: ${x.icp} in ${esc(state.params.region)}.</p></section><section><h3>Solution and technology</h3><p>${esc(ctx.solution)}</p></section><section><h3>RACI and timelines</h3><p>${esc(ctx.plan)}</p></section><section><h3>Finances and ROI</h3><p>Offer price: ${money(x.price)}. ${finance?`Investment model: ${money(x.investment)}. Net operating cash flow: ${money(x.monthlyCash)} per month. Expected ROI over ${state.params.roi} months: ${finance.roi}%; payback ${number(finance.payback)} months.`:`Planned investment: ${money(x.investment)}. Assumed net cash flow: ${money(x.monthlyCash)} per month. Expected ROI over ${state.params.roi} months: ${model.roi}%; payback ${number(model.payback)} months. This is an estimate before market testing.`}</p></section><section><h3>${stage>=2?'GTM and catalog':'Proposed channels'}</h3><p>${esc(ctx.channels)} Demo addressable audience: ${number(1000+id*87)} potential customers.</p></section>${ideaScoreSummary(x,stage)}</div>${finance?`<div class="phase-banner" style="margin-top:20px;margin-bottom:0">${ico('check')}<span>${x.preorders} demo preorders · ${money(finance.revenue)} in value</span></div>`:''}<p class="small-note">The financial model is illustrative: ROI = (monthly net cash flow × period − investment) / investment. Preorders represent the value of simulated agreed orders, without proof of payment. They are not realized revenue.</p>`);bindScoreLinks();}
function agentsView(){return `${heading('THE TEAM THAT TESTS YOUR IDEAS','24 agents. One clearer decision.','Experts from different disciplines evaluate every idea independently.',statusPill('Demo team'))}<div class="rubric-strip"><div class="rubric-item accent"><strong>24</strong><small>expert agents</small></div><div class="rubric-item"><strong>4</strong><small>areas of expertise</small></div><div class="rubric-item"><strong>4</strong><small>evaluation stages</small></div><div class="rubric-item"><strong>100%</strong><small>independent scores</small></div></div><div class="agents-toolbar"><div class="filter-tabs">${['All agents','Product','Capital','Growth','Operations'].map(c=>`<button class="filter-tab ${agentCategory===c?'active':''}" data-category="${c}" aria-pressed="${agentCategory===c}">${c}${c==='All agents'?' · 24':''}</button>`).join('')}</div><label class="search-box">${ico('search')}<input id="agent-search" aria-label="Search agents" value="${esc(agentSearch)}" placeholder="Search agents…"></label></div><div class="agents-grid" id="agents-grid">${agentCards()}</div><p class="small-note">In a real process, agents would be configured experts. This prototype shows their roles and simulated independent scores without connecting to an AI service.</p>`;}
function agentCards(){return (window.AGENTS||[]).filter(a=>(agentCategory==='All agents'||a.category===agentCategory)&&`${a.name} ${a.role} ${a.description}`.toLocaleLowerCase().includes(agentSearch.toLocaleLowerCase())).map(a=>`<article class="agent-card"><div class="agent-card-top"><span class="agent-avatar ${esc(a.category)}">${esc(a.role.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><span class="agent-category">${esc(a.category).toUpperCase()}</span></div><h3>${esc(a.name)}</h3><span class="agent-role">${esc(a.role)}</span><p class="agent-description">${esc(a.description)}</p><div class="agent-card-bottom"><span>All 4 stages · independent score</span><button data-agent="${esc(a.id)}">Agent details ${ico('arrow')}</button></div></article>`).join('')||'<div class="agent-no-results">No agents match your search.</div>';}
function bindAgents(){ $$('[data-agent]').forEach(b=>b.onclick=()=>{const a=window.AGENTS.find(a=>String(a.id)===b.dataset.agent);showDialog(`<div class="dialog-kicker">${esc(a.category)} · INDEPENDENT EVALUATOR</div><h2>${esc(a.name)}</h2><p class="dialog-text">${esc(a.description)}</p><div class="dialog-grid"><section><h3>Input</h3><p>${esc(a.input)}</p></section><section><h3>Output</h3><p>${esc(a.output)}</p></section></div><h3 style="margin-top:20px">How this agent contributes</h3><p class="dialog-text">Evaluates each idea within its area of expertise on a 0–100 scale, independently of other agents. PMF and GTM use the average of all 24 scores. Marketing combines metrics (60%) with the average agent score (40%). Sales adds a risk assessment alongside preorders.</p><p class="small-note">Demo role and scores. This agent does not execute real tasks or use external data.</p>`);});}
function resultsView(){const n=completedCount();if(n===0)return `${heading('EVIDENCE AND DECISIONS IN ONE PLACE','Your project results','Track selected ideas and their business metrics.')}<div class="empty-state">${ico('chart')}<h2>Your first results start with an idea.</h2><p>Create a project and complete Product Market Fit. You will see ranked ideas here, followed by demo preorders, ROI and payback estimates.</p><button class="button primary" id="return-project">Open project${ico('arrow')}</button></div>`;const stage=completedIds().includes(resultStagePreference)?resultStagePreference:Math.max(...completedIds());const rows=rankedIdeas(stage),final=stage===4;const total=final?rows.reduce((n,x)=>n+x.preorders,0):0;const revenue=final?rows.reduce((n,x)=>n+financial(x).revenue,0):0;return `${heading('FROM PARAMETERS TO MARKET SIGNALS','Your project results',esc(state.params.name)+' · All values are demo data.',statusPill(final?'All stages complete':`${n} / 4 stages complete`,final?'complete':''))}<div class="result-stats"><div class="stat-card"><small>Selected business ideas</small><strong>${rows.length}</strong><p>After ${PHASES[stage-1].short}</p></div><div class="stat-card highlight"><small>Demo preorders</small><strong>${final?number(total):'—'}</strong><p>${final?'Simulated customer confirmations':'Available after Sales'}</p></div><div class="stat-card"><small>Preorder value</small><strong>${final?money(revenue):'—'}</strong><p>${final?'Total across alternative demo ideas':'Available after Sales'}</p></div><div class="stat-card"><small>Target payback period</small><strong>${state.params.roi} <span style="font-size:13px">mo.</span></strong><p>Your input parameter</p></div></div><div class="panel-title-row"><div class="filter-tabs">${completedIds().map(s=>`<button class="filter-tab ${stage===s?'active':''}" data-result-stage="${s}" aria-pressed="${stage===s}">${PHASES[s-1].short}</button>`).join('')}</div><button class="button secondary" id="export-project">${ico('download')}Export project</button></div><div id="result-table-container">${resultsTable(stage)}</div><p class="small-note">Ideas are alternative business scenarios. Total preorder value is not a revenue forecast for one business. Each idea has its own investment, assumed net cash flow and payback model. All confirmations are simulated.</p>`;}
let visibleResultStage=1;
function bindTable(stage){visibleResultStage=stage;bindScoreLinks();$$('[data-idea]').forEach(b=>b.onclick=()=>showIdea(Number(b.dataset.idea),stage));if($('#export-csv'))$('#export-csv').onclick=()=>exportCSV(stage);if($('#toggle-all'))$('#toggle-all').onclick=()=>{showAll=!showAll;refreshTable(stage);};if($('#toggle-eliminated'))$('#toggle-eliminated').onclick=()=>{showEliminated=!showEliminated;refreshTable(stage);};}
function refreshTable(stage){if(route==='results')$('#result-table-container').innerHTML=resultsTable(stage);else $('.results-panel').outerHTML=resultsTable(stage);bindTable(stage);}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Your export is ready.');}
function exportCSV(stage){const rows=rankedIdeas(stage,showEliminated);const header=['ID','Idea','PMF score','GTM score','Marketing score','Price EUR','Visits','Email replies','Newsletter subscriptions','Demo preorders','Preorder value EUR','ROI percent','Payback months','Data'];const data=rows.map(x=>[x.id,x.name,x.score,stage>=2?x.gtmScore:'',stage>=3?x.marketingScore:'',x.price,stage>=3?x.visits:'',stage>=3?x.replies:'',stage>=3?x.subscribers:'',stage===4?x.preorders:'',stage===4?financial(x).revenue:'',financial(x).roi,financial(x).payback,'DEMO SIMULATION']);const safe=v=>{const s=String(v??'');return /^[=+\-@\t\r]/.test(s)?"'"+s:s;};download('\ufeff'+[header,...data].map(row=>row.map(x=>'"'+safe(x).replace(/"/g,'""')+'"').join(';')).join('\r\n'),'business-engine-'+PHASES[stage-1].short.toLowerCase().replaceAll(' ','-')+'.csv','text/csv;charset=utf-8');}
function exportProject(){download(JSON.stringify({application:'FORGE Business Engine',dataType:'DEMO',exportedAt:new Date().toISOString(),project:state,results:completedIds().map(stage=>({phase:PHASES[stage-1].name,ideas:rankedIdeas(stage).map(x=>({...x,financialModel:financial(x)}))}))},null,2),'business-engine-project.json','application/json');}
function showDialog(html){$('#dialog-content').innerHTML=html;$('#detail-dialog').showModal();}
function help(){showDialog(`<div class="dialog-kicker">BUSINESS ENGINE / GUIDE</div><h2>Your businesses, from idea to operation</h2><p class="dialog-text">My business brings all your businesses together. New business starts a separate wizard, and each detail page holds preparation, validation and operating information. This demo follows the Business Engine document. Each of the four stages can be a standalone product; here they are connected in one wizard.</p><ol class="help-list"><li><strong>Parameters:</strong> name, industry, capital, target payback period, founder strengths and existing channels.</li><li><strong>Product Market Fit:</strong> 100 ideas and business plans → top 50.</li><li><strong>Go-To-Market:</strong> region, ICP, pricing, catalog and channels → 30 ideas.</li><li><strong>Marketing:</strong> equal budgets, visits, email replies and subscriptions → 15 ideas.</li><li><strong>Sales:</strong> order pages and larger budgets → demo preorders, ROI and payback per idea.</li></ol><p class="dialog-text">Processes take 18–24 seconds in this demo. You can pause, resume and review their results. The real-world durations shown are illustrative; the document specifically allows several weeks for Marketing.</p><p class="small-note">The 24 AI experts, campaigns, websites and orders are simulated. There are no external service connections or payments. Projects are saved locally in your browser.</p>`);}
function render(){
 sidebar();
 $('#breadcrumb-page').textContent=route==='businesses'?'My business':route==='business'?state.params.name:route==='agents'?'Agent team':route==='evaluations'?'Agent scores · '+state.params.name:route==='results'?'Results · '+state.params.name:state.params.name||'New business';
 const app=$('#app');
 if(route==='businesses'){app.innerHTML=window.BusinessViews.home(portfolio);window.BusinessViews.bindHome(portfolio,businessHandlers());return;}
 if(route==='business'){app.innerHTML=window.BusinessViews.detail(state);window.BusinessViews.bindDetail(state,businessHandlers());return;}
 if(route==='evaluations'){app.innerHTML=window.AgentEvaluations.render(evaluationPayload(evaluationSelection.stage,evaluationSelection.id,evaluationSelection.origin));return;}
 app.innerHTML=route==='agents'?agentsView():route==='results'?resultsView():state.activeStep===0?setup():phaseView();paintIcons(app);
 $$('[data-step]',app).forEach(b=>b.onclick=()=>openStep(Number(b.dataset.step)));
 if(route==='project'){
   if(state.activeStep===0){$('#project-form').onsubmit=e=>{e.preventDefault();commitForm(true);};$('#save-draft').onclick=()=>commitForm(false);$('#wizard-back').onclick=()=>portfolio.activeId?openBusiness(state.id):routeTo('businesses');}
   else{const i=state.activeStep-1;if($('#run-phase'))$('#run-phase').onclick=()=>runPhase(i);if($('#resume-phase'))$('#resume-phase').onclick=()=>runPhase(i);if($('#pause-phase'))$('#pause-phase').onclick=()=>pausePhase(i);if($('#back-phase'))$('#back-phase').onclick=()=>openStep(i);$$('[data-next]').forEach(b=>b.onclick=()=>openStep(Number(b.dataset.next)));if($('#go-results'))$('#go-results').onclick=()=>routeTo('results');if(state.phases[i].status==='complete')bindTable(i+1);}
 }
 if(route==='agents'){$$('[data-category]').forEach(b=>b.onclick=()=>{agentCategory=b.dataset.category;$$('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$('#agents-grid').innerHTML=agentCards();bindAgents();});$('#agent-search').oninput=e=>{agentSearch=e.target.value;$('#agents-grid').innerHTML=agentCards();bindAgents();};bindAgents();}
 if(route==='results'){if($('#return-project'))$('#return-project').onclick=()=>routeTo('project');if(completedCount()){bindTable(completedIds().includes(resultStagePreference)?resultStagePreference:Math.max(...completedIds()));$$('[data-result-stage]').forEach(b=>b.onclick=()=>{showAll=false;showEliminated=false;resultStagePreference=Number(b.dataset.resultStage);$$('[data-result-stage]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$('#result-table-container').innerHTML=resultsTable(Number(b.dataset.resultStage));bindTable(Number(b.dataset.resultStage));});$('#export-project').onclick=exportProject;}}
}
function changeRoute(){
 const parts=location.hash.slice(1).split('/');
 let desired=['businesses','business','project','agents','results','evaluations'].includes(parts[0])?parts[0]:'businesses';
 if(['business','project','results','evaluations'].includes(desired)&&parts[1]){let id;try{id=decodeURIComponent(parts[1]);}catch(e){}if(!id||!selectBusiness(id)){desired='businesses';toast('This business was not found in this browser.');}}
 if(desired==='business'&&!portfolio.activeId)desired='businesses';
 resultStagePreference=desired==='results'?Number(parts[2])||0:0;
 if(desired==='evaluations'){
   const stage=Number(parts[2]),id=Number(parts[3]);
   if(!parts[1]||!portfolio.activeId||!evaluationRouteValid(stage,id)){desired=portfolio.activeId?'business':'businesses';toast('This evaluation is unavailable. Complete the stage before reviewing its scores.');}
   else{evaluationSelection={stage,id,origin:parts[4]==='results'?'results':'project'};state.activeStep=stage;persist();}
 }
 route=desired;$('#sidebar').classList.remove('open');showAll=false;showEliminated=false;render();window.scrollTo(0,0);
}

$('#help-button').onclick=help;$('.dialog-close').onclick=()=>$('#detail-dialog').close();$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');document.addEventListener('click',e=>{if(innerWidth<=740&&!e.target.closest('#sidebar')&&!e.target.closest('#menu-toggle'))$('#sidebar').classList.remove('open');});window.addEventListener('hashchange',changeRoute);paintIcons();changeRoute();tick();setInterval(tick,500);
